            // post.combiner[i] = CombinerState::Appending{cur_idx + 1, pre.tail}
            // post.combiner[j] = pre.combiner[j] (unchanged)

            let CombinerState::Appending{cur_idx: new_cur_idx, tail: new_tail} = post.combiner[i];
            // new_cur_idx = cur_idx + 1, new_tail = pre.tail

            if post.combiner[j].is_Appending() {
                let CombinerState::Appending{cur_idx: cur_idx2, tail: tail2} = post.combiner[j];
                // pre.combiner[i] = CombinerState::Appending{cur_idx, pre.tail}
                // pre.combiner[j] = CombinerState::Appending{cur_idx2, tail2}

