                // This gives us: (cur_idx >= tail2) || (pre.tail <= cur_idx2)
                // If pre.tail <= cur_idx2, we're done
                // Otherwise, cur_idx >= tail2, which means cur_idx + 1 > tail2, so cur_idx + 1 >= tail2
            } else if post.combiner[j].is_Reading() && post.combiner[j].get_Reading_0().is_Guard() {
                let guard = post.combiner[j].get_Reading_0().get_Guard();
                let cur = guard.cur;
                let start = guard.start;
                let end = guard.end;
