                // We need to show:
                // (new_cur_idx > cur) || (new_tail <= cur)
                // Which is:
                // (cur_idx + 1 > cur) || (pre.tail <= cur)

                assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
                // This gives us: (cur_idx > cur) || (pre.tail <= cur)
                // If pre.tail <= cur, we're done
                // Otherwise, cur_idx > cur, which means cur_idx + 1 > cur
