                // We need to show:
                // (cur_idx2 >= new_tail) || (tail2 <= new_cur_idx)
                // Which is:
                // (cur_idx2 >= pre.tail) || (tail2 <= cur_idx + 1)

                assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
                // This gives us: (cur_idx2 >= pre.tail) || (tail2 <= cur_idx)
                // If cur_idx2 >= pre.tail, we're done
                // Otherwise, tail2 <= cur_idx, which means tail2 <= cur_idx + 1
            } else if post.combiner[i].is_Reading() && post.combiner[i].get_Reading_0().is_Guard() {
                let guard = post.combiner[i].get_Reading_0().get_Guard();
                let cur = guard.cur;
                // pre.combiner[i] = CombinerState::Reading(Guard{..., cur, ...})
                // pre.combiner[j] = CombinerState::Appending{cur_idx, pre.tail}

                // By pre invariant:
                // (cur_idx > cur) || (pre.tail <= cur)
                // We need to show:
                // (cur > new_cur_idx) || (new_tail <= cur)
                // Which is:
                // (cur > cur_idx + 1) || (pre.tail <= cur)

                assert(pre.combiner[i].no_overlap_with(pre.combiner[j]));
