    // We need to show that for all i where post.tail <= i < min_local_head + post.buffer_size:
    // !log_entry_is_alive(post.alive_bits, i, post.buffer_size)

    let min_local_head = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);
    assert forall |i| post.tail <= i < min_local_head + post.buffer_size implies 
        !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {

        // Since tail didn't change (only cur_idx changed), and local_versions didn't change,
        // min_local_head is the same in pre and post.
        // By pre invariant, we know that for all i where pre.tail <= i < min_local_head + pre.buffer_size:
        // !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)

        // The only bit that changed is alive_bits[log_entry_idx(cur_idx as int, pre.buffer_size)],
        // where cur_idx < pre.tail (by the transition requirement), so cur_idx is not in the range
        // [pre.tail, min_local_head + pre.buffer_size), so this change doesn't affect the invariant.

        assert(post.tail == pre.tail);
        assert(post.local_versions === pre.local_versions);
        assert(post.alive_bits.contains_key(log_entry_idx(cur_idx as int, pre.buffer_size)));
        assert(log_entry_idx(cur_idx as int, pre.buffer_size) == log_entry_idx(i, pre.buffer_size) ==> post.alive_bits[log_entry_idx(cur_idx as int, pre.buffer_size)] != pre.alive_bits[log_entry_idx(cur_idx as int, pre.buffer_size)]);

        // Since cur_idx < pre.tail <= i, we have cur_idx != i, so the change to alive_bits at
        // log_entry_idx(cur_idx as int, pre.buffer_size) doesn't affect alive_bits at log_entry_idx(i, pre.buffer_size).
    }
}

