                    // pre condition: (cur_idx >= tail2) || (tail <= cur_idx2)
                    // post condition: (cur_idx + 1 >= tail2) || (tail <= cur_idx2)

                    // Since pre satisfied the invariant, we have (cur_idx >= tail2) || (tail <= cur_idx2)
                    // If (tail <= cur_idx2), then post also satisfies it
                    // Otherwise, (cur_idx >= tail2), which implies (cur_idx + 1 >= tail2)
                    assert((cur_idx >= tail2) || (tail <= cur_idx2)); // by pre invariant
                    if tail <= cur_idx2 {
                        assert((cur_idx + 1 >= tail2) || (tail <= cur_idx2));
                    } else {
                        assert(cur_idx >= tail2);
                        assert(cur_idx + 1 >= tail2);
                        assert((cur_idx + 1 >= tail2) || (tail <= cur_idx2));
                    }
                },
                _ => {
                    // For all other cases, no_overlap_with returns true
                    assert(true);
                }
