        assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)); // by pre invariant
        assert(log_entry_idx(cur_idx as int, pre.buffer_size) != log_entry_idx(i as int, pre.buffer_size)); // because cur_idx < pre.tail <= i
