        assert(!log_entry_is_alive(post.alive_bits, i, post.buffer_size));
    }

    // We also need to show that the other invariants still hold.
    // Most of them are straightforward since only combiner[node_id] and alive_bits[log_entry_idx(cur_idx, buffer_size)] changed.
}

