            // post.combiner[i].no_overlap_with(post.combiner[j])
            // Which means: CombinerState::Appending{cur_idx + 1, tail}.no_overlap_with(pre.combiner[j])

            // Let's look at the cases in no_overlap_with:
            // For CombinerState::Appending{cur_idx + 1, tail} and pre.combiner[j]:
            match pre.combiner[j] {
                CombinerState::Reading(ReaderState::Guard{start, end, cur, val}) => {
                    // pre condition: (cur_idx > cur) || (tail <= cur)
                    // post condition: (cur_idx + 1 > cur) || (tail <= cur)

                    // Since pre satisfied the invariant, we have (cur_idx > cur) || (tail <= cur)
                    // If (tail <= cur), then post also satisfies it
                    // Otherwise, (cur_idx > cur), which implies (cur_idx + 1 > cur)
                    assert((cur_idx > cur) || (tail <= cur)); // by pre invariant
