                            // For Appending vs Appending:
                            // pre condition: (cur_idx2 >= tail) || (tail2 <= cur_idx)
                            // post condition: (cur_idx2 >= tail) || (tail2 <= cur_idx + 1)

                            // Since pre satisfied the invariant, we have (cur_idx2 >= tail) || (tail2 <= cur_idx)
                            // If (cur_idx2 >= tail), then post also satisfies it
                            // Otherwise, (tail2 <= cur_idx), which implies (tail2 <= cur_idx + 1)
                            assert((cur_idx2 >= tail) || (tail2 <= cur_idx)); // by pre invariant
                            if cur_idx2 >= tail {
                                assert((cur_idx2 >= tail) || (tail2 <= cur_idx + 1));
                            } else {
                                assert(tail2 <= cur_idx);
                                assert(tail2 <= cur_idx + 1);
                                assert((cur_idx2 >= tail) || (tail2 <= cur_idx + 1));
                            }
