#[inductive(append_flip_bit)]
fn append_flip_bit_inductive(pre: Self, post: Self, node_id: NodeId, deposited: StoredType<DT>) { 
    // Since this is an inductive proof for append_flip_bit transition, we know that
    // pre.combiner[node_id] must be CombinerState::Appending{cur_idx, tail} for some cur_idx, tail
    // and that cur_idx < tail (from the transition's require clause).

    match pre.combiner[node_id] {
        CombinerState::Appending{cur_idx, tail} => {
            // For ranges_no_overlap invariant:
            // We need to show that for all i,j where i != j:
            // post.combiner[i].no_overlap_with(post.combiner[j])

            assert forall |i, j| post.combiner.contains_key(i) && post.combiner.contains_key(j) && i != j implies
                post.combiner[i].no_overlap_with(post.combiner[j]) by {

                // Case 1: Neither i nor j is node_id - nothing changed for these combinators
                if i != node_id && j != node_id {
                    assert(pre.combiner[i].no_overlap_with(pre.combiner[j])); // by pre invariant
                    assert(post.combiner[i] === pre.combiner[i]);
                    assert(post.combiner[j] === pre.combiner[j]);
                }
                // Case 2: One of them is node_id
                else if i == node_id && j != node_id {
                    // post.combiner[i] = CombinerState::Appending{cur_idx + 1, tail}
                    // post.combiner[j] = pre.combiner[j] (unchanged)

                    // By the pre invariant (all_combiner_valid), we have:
                    // pre.combiner[node_id].no_overlap_with(pre.combiner[j])
                    // Which means: CombinerState::Appending{cur_idx, tail}.no_overlap_with(pre.combiner[j])

                    // We need to show:
                    // post.combiner[i].no_overlap_with(post.combiner[j])
                    // Which means: CombinerState::Appending{cur_idx + 1, tail}.no_overlap_with(pre.combiner[j])

                    match pre.combiner[j] {
                        CombinerState::Reading(ReaderState::Guard{start, end, cur, val}) => {
                            // For Appending{cur_idx, tail} vs Reading(Guard{..., cur, ...}):
                            // Condition is: (cur_idx > cur) || (tail <= cur)
                            // For Appending{cur_idx + 1, tail} vs Reading(Guard{..., cur, ...}):
                            // Condition is: (cur_idx + 1 > cur) || (tail <= cur)

                            // By pre invariant, we have: (cur_idx > cur) || (tail <= cur)
                            // Need to show: (cur_idx + 1 > cur) || (tail <= cur)
                            // If (tail <= cur), we're done.
                            // Otherwise, (cur_idx > cur), so (cur_idx + 1 > cur).
                            assert((cur_idx > cur) || (tail <= cur)); // by pre invariant
                            if tail <= cur {
                                assert((cur_idx + 1 > cur) || (tail <= cur));
                            } else {
                                assert(cur_idx > cur);
                                assert(cur_idx + 1 > cur);
                                assert((cur_idx + 1 > cur) || (tail <= cur));
                            }
                        },
                        CombinerState::Appending{cur_idx: cur_idx2, tail: tail2} => {
                            // For Appending{cur_idx, tail} vs Appending{cur_idx2, tail2}:
                            // Condition is: (cur_idx >= tail2) || (tail <= cur_idx2)
                            // For Appending{cur_idx + 1, tail} vs Appending{cur_idx2, tail2}:
                            // Condition is: (cur_idx + 1 >= tail2) || (tail <= cur_idx2)

                            // By pre invariant, we have: (cur_idx >= tail2) || (tail <= cur_idx2)
                            // Need to show: (cur_idx + 1 >= tail2) || (tail <= cur_idx2)
                            // If (tail <= cur_idx2), we're done.
                            // Otherwise, (cur_idx >= tail2), so (cur_idx + 1 >= tail2).
                            assert((cur_idx >= tail2) || (tail <= cur_idx2)); // by pre invariant
                            if tail <= cur_idx2 {
                                assert((cur_idx + 1 >= tail2) || (tail <= cur_idx2));
                            } else {
                                assert(cur_idx >= tail2);
                                assert(cur_idx + 1 >= tail2);
                                assert((cur_idx + 1 >= tail2) || (tail <= cur_idx2));
                            }
                        },
                        _ => {
                            // For all other cases, no_overlap_with returns true
                            assert(true);
                        }
                    }
                } else if i != node_id && j == node_id {
                    // post.combiner[i] = pre.combiner[i] (unchanged)
                    // post.combiner[j] = CombinerState::Appending{cur_idx + 1, tail}

                    // By the pre invariant (all_combiner_valid), we have:
                    // pre.combiner[i].no_overlap_with(pre.combiner[node_id])
                    // Which means: pre.combiner[i].no_overlap_with(CombinerState::Appending{cur_idx, tail})

                    // We need to show:
                    // post.combiner[i].no_overlap_with(post.combiner[j])
                    // Which means: pre.combiner[i].no_overlap_with(CombinerState::Appending{cur_idx + 1, tail})

                    match pre.combiner[i] {
                        CombinerState::Reading(ReaderState::Guard{start, end, cur, val}) => {
                            // For Reading(Guard{..., cur, ...}) vs Appending{cur_idx, tail}:
                            // Condition is: (cur_idx > cur) || (tail <= cur)
                            // For Reading(Guard{..., cur, ...}) vs Appending{cur_idx + 1, tail}:
                            // Condition is: (cur_idx + 1 > cur) || (tail <= cur)

                            // By pre invariant, we have: (cur_idx > cur) || (tail <= cur)
                            // Need to show: (cur_idx + 1 > cur) || (tail <= cur)
                            // If (tail <= cur), we're done.
                            // Otherwise, (cur_idx > cur), so (cur_idx + 1 > cur).
                            assert((cur_idx > cur) || (tail <= cur)); // by pre invariant
                            if tail <= cur {
                                assert((cur_idx + 1 > cur) || (tail <= cur));
                            } else {
                                assert(cur_idx > cur);
                                assert(cur_idx + 1 > cur);
                                assert((cur_idx + 1 > cur) || (tail <= cur));
                            }
                        },
                        CombinerState::Appending{cur_idx: cur_idx2, tail: tail2} => {
                            // For Appending{cur_idx2, tail2} vs Appending{cur_idx, tail}:
                            // Condition is: (cur_idx2 >= tail) || (tail2 <= cur_idx)
                            // For Appending{cur_idx2, tail2} vs Appending{cur_idx + 1, tail}:
                            // Condition is: (cur_idx2 >= tail) || (tail2 <= cur_idx + 1)

                            // By pre invariant, we have: (cur_idx2 >= tail) || (tail2 <= cur_idx)
                            // Need to show: (cur_idx2 >= tail) || (tail2 <= cur_idx + 1)
                            // If (cur_idx2 >= tail), we're done.
                            // Otherwise, (tail2 <= cur_idx), so (tail2 <= cur_idx + 1).
                            assert((cur_idx2 >= tail) || (tail2 <= cur_idx)); // by pre invariant
                            if cur_idx2 >= tail {
                                assert((cur_idx2 >= tail) || (tail2 <= cur_idx + 1));
                            } else {
                                assert(tail2 <= cur_idx);
                                assert(tail2 <= cur_idx + 1);
                                assert((cur_idx2 >= tail) || (tail2 <= cur_idx + 1));
                            }
                        },
                        _ => {
                            // For all other cases, no_overlap_with returns true
                            assert(true);
                        }
                    }
                }
            }

            // For upcoming_bits_are_not_alive invariant:
            // We need to show that for all i where post.tail <= i < min_local_head + post.buffer_size:
            // !log_entry_is_alive(post.alive_bits, i, post.buffer_size)

            let min_local_head = map_min_value(post.local_versions, (post.num_replicas - 1) as nat);
            assert forall |i| post.tail <= i < min_local_head + post.buffer_size implies 
                !log_entry_is_alive(post.alive_bits, i, post.buffer_size) by {

                // Key observations:
                // 1. post.tail == pre.tail (tail is not modified in this transition)
                // 2. post.local_versions == pre.local_versions (local_versions is not modified)
                // 3. Therefore, min_local_head is the same in pre and post
                // 4. The only change to alive_bits is at index log_entry_idx(cur_idx, pre.buffer_size)
                // 5. cur_idx < pre.tail (requirement in the transition)

                assert(post.tail == pre.tail);
                assert(post.local_versions === pre.local_versions);

                // By pre invariant (upcoming_bits_are_not_alive), we know that for all i where pre.tail <= i < min_local_head + pre.buffer_size:
                // !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)

                // We need to show the same for post.
                // Since post.alive_bits differs from pre.alive_bits only at index log_entry_idx(cur_idx, pre.buffer_size),
                // and cur_idx < pre.tail <= i, we have cur_idx != i.
                // For typical buffer sizes, log_entry_idx(cur_idx, pre.buffer_size) != log_entry_idx(i, pre.buffer_size).
                // Therefore, post.alive_bits at log_entry_idx(i, pre.buffer_size) equals pre.alive_bits at the same index, so:
                // !log_entry_is_alive(post.alive_bits, i, post.buffer_size) == !log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)

                // The key point is that since cur_idx < pre.tail <= i, the bit we flipped is not in the range
                // we're checking, so the invariant is preserved.
                assert(!log_entry_is_alive(pre.alive_bits, i, pre.buffer_size)); // by pre invariant (upcoming_bits_are_not_alive)
                // We can conclude that !log_entry_is_alive(post.alive_bits, i, post.buffer_size) since the only bit that changed
                // is at log_entry_idx(cur_idx, pre.buffer_size), which is different from log_entry_idx(i, pre.buffer_size).
                assert(!log_entry_is_alive(post.alive_bits, i, post.buffer_size));
            }

            // For inv_buffer_contents invariant:
            // Need to show:
            // 1. forall |i: int| post.tail - post.buffer_size <= i < post.tail ==> (
            //      (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
            //          i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
            //      <==>
            //      #[trigger] post.contents.contains_key(i)
            //    )
            // 2. forall |i: int| post.tail <= i ==> ! #[trigger] post.contents.contains_key(i)

            assert forall |i: int| post.tail - post.buffer_size <= i < post.tail implies
                ((log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                    i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
                <==> #[trigger] post.contents.contains_key(i)) by {

                // Key facts:
                // 1. post.tail == pre.tail
                // 2. post.buffer_size == pre.buffer_size
                // 3. post.local_versions == pre.local_versions
                // 4. post.contents == pre.contents.insert(cur_idx as int, deposited)
                // 5. cur_idx < pre.tail

                assert(post.contents.contains_key(i) == (pre.contents.contains_key(i) || i == cur_idx as int));

                if i == cur_idx as int {
                    // We added this entry, so post.contents.contains_key(i) is true
                    // We need to show that:
                    // (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                    //   i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
                    // is also true

                    // Since we just made this entry alive (that's the whole point of the transition),
                    // log_entry_is_alive(post.alive_bits, i, post.buffer_size) should be true.
                    // In the transition, we set:
                    // alive_bits[log_entry_idx(cur_idx as int, pre.buffer_size)] = log_entry_alive_value(cur_idx as int, pre.buffer_size)
                    // So log_entry_is_alive(post.alive_bits, cur_idx as int, post.buffer_size) is true by definition.
                    assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size));
                    assert((log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                        i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat)));
                } else {
                    // post.contents.contains_key(i) == pre.contents.contains_key(i)
                    // By pre invariant, we have:
                    // (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) ||
                    //   i < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat))
                    // <==> pre.contents.contains_key(i)
                    //
                    // We need to show:
                    // (log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                    //   i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
                    // <==> post.contents.contains_key(i)
                    //
                    // Since post.local_versions == pre.local_versions, we just need to check the alive_bits part.
                    // The only change to alive_bits is at index log_entry_idx(cur_idx, pre.buffer_size).
                    // Since i != cur_idx, we have log_entry_idx(i, pre.buffer_size) != log_entry_idx(cur_idx, pre.buffer_size)
                    // (assuming reasonable buffer size), so post.alive_bits[log_entry_idx(i, pre.buffer_size)] == pre.alive_bits[log_entry_idx(i, pre.buffer_size)].
                    // Thus log_entry_is_alive(post.alive_bits, i, post.buffer_size) == log_entry_is_alive(pre.alive_bits, i, pre.buffer_size).
                    assert(log_entry_is_alive(post.alive_bits, i, post.buffer_size) == log_entry_is_alive(pre.alive_bits, i, pre.buffer_size));
                    assert((log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                        i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
                       == (log_entry_is_alive(pre.alive_bits, i, pre.buffer_size) ||
                        i < map_min_value(pre.local_versions, (pre.num_replicas - 1) as nat)));
                    assert((log_entry_is_alive(post.alive_bits, i, post.buffer_size) ||
                        i < map_min_value(post.local_versions, (post.num_replicas - 1) as nat))
                       <==> post.contents.contains_key(i));
                }
            }

            assert forall |i: int| post.tail <= i implies ! #[trigger] post.contents.contains_key(i) by {
                // post.contents == pre.contents.insert(cur_idx as int, deposited)
                // For i >= post.tail, we have i != cur_idx (since cur_idx < pre.tail == post.tail)
                // So post.contents.contains_key(i) == pre.contents.contains_key(i)
                // By pre invariant, !pre.contents.contains_key(i)
                assert(!post.contents.contains_key(i));
            }

            // We also need to show that the other invariants still hold.
            // Most of them are straightforward since only combiner[node_id] and alive_bits[log_entry_idx(cur_idx, buffer_size)] changed.
        },
        _ => {
            // This case should be impossible because of the transition precondition
            assert(false);
        }
    }
}

